class RecordingsPage{constructor(){this.init();}init(){this.render();this.initializeStandaloneRecordings();}render(){const container=document.getElementById('recordings');if(!container)return;if(!document.querySelector('link[href*="recordings-camera-list.css"]')){const link=document.createElement('link');link.rel='stylesheet';link.href='src/styles/recordings-camera-list.css';document.head.appendChild(link);}container.innerHTML=` <div class="page-container"> <!--Sidebar--> <div class="sidebar"> <div class="sidebar-header"> <h2><i class="fas fa-video"></i> Recordings</h2> </div> <!--Controls section below header--> <div class="sidebar-controls"> <!--Service Status Indicator--> <div class="service-status checking" id="serviceStatus"> <span class="status-indicator"></span> <span id="serviceStatusText">Checking service...</span> </div> <!--Camera List(Date-based)--> <div class="camera-list-container"> <div class="camera-list-header"> <h3>Cameras</h3> <span id="cameraCount">Select a date</span> </div> <div class="camera-list" id="cameraList"> <div class="camera-list-placeholder"> <i class="fas fa-calendar"></i> <p>Select a date to see available cameras</p> </div> </div> </div> </div> <!--Calendar--> <div class="calendar-container"> <div class="calendar-header"> <span id="calendarMonth">Loading...</span> <div class="calendar-nav"> <button id="prevMonth" disabled><i class="fas fa-chevron-left"></i></button> <button id="todayBtn" disabled>Today</button> <button id="nextMonth" disabled><i class="fas fa-chevron-right"></i></button> </div> </div> <div class="calendar-weekdays"> <div class="calendar-weekday">S</div> <div class="calendar-weekday">M</div> <div class="calendar-weekday">T</div> <div class="calendar-weekday">W</div> <div class="calendar-weekday">T</div> <div class="calendar-weekday">F</div> <div class="calendar-weekday">S</div> </div> <div class="calendar-grid" id="calendarGrid"> <!--Calendar skeleton loading--> <div class="calendar-day skeleton"></div> <div class="calendar-day skeleton"></div> <div class="calendar-day skeleton"></div> <div class="calendar-day skeleton"></div> <div class="calendar-day skeleton"></div> <div class="calendar-day skeleton"></div> <div class="calendar-day skeleton"></div> </div> </div> <!--Timeline--> <div class="timeline-container"> <div class="timeline-header"> <h3>Recordings</h3> <span id="recordingCount">--</span> </div> <div id="recordingsList"> <!--Loading skeleton--> <div class="skeleton skeleton-item"></div> <div class="skeleton skeleton-item"></div> <div class="skeleton skeleton-item"></div> </div> </div> </div> <!--Main Content--> <div class="recordings-content"> <!--Video Player--> <div class="video-container"> <div class="video-placeholder" id="videoPlaceholder"> <i class="fas fa-video"></i> <p>Select a recording to begin playback</p> </div> <video id="videoPlayer" controls style="display:none;"> Your browser does not support video playback. </video> <div class="video-loading" id="videoLoading" style="display:none;"> <i class="fas fa-spinner"></i> <p>Loading video...</p> </div> <div class="video-error" id="videoError" style="display:none;"> <i class="fas fa-exclamation-circle"></i> <h3>Unable to Play Video</h3> <p>Please try a different recording or check your connection.</p> </div> </div> <!--Controls--> <div class="controls-bar"> <div class="timeline-scrubber"> <div class="timeline-track" id="timelineTrack"> <!--Timeline segments will be rendered here--> </div> <div class="timeline-time-labels"> <span>00:00</span> <span>06:00</span> <span>12:00</span> <span>18:00</span> <span>24:00</span> </div> </div> <div class="playback-controls"> <button class="control-btn" id="skipBackBtn" disabled> <i class="fas fa-backward"></i> </button> <button class="control-btn" id="playPauseBtn" disabled> <i class="fas fa-play"></i> </button> <button class="control-btn" id="skipForwardBtn" disabled> <i class="fas fa-forward"></i> </button> <span class="time-display" id="timeDisplay">--:--:--/--:--:--</span> <div class="speed-selector"> <select id="speedSelect" disabled> <option value="0.5">0.5x</option> <option value="1" selected>1x</option> <option value="1.5">1.5x</option> <option value="2">2x</option> <option value="4">4x</option> </select> </div> </div> </div> </div> </div> `;}initializeStandaloneRecordings(){const script=document.createElement('script');script.textContent=` const CONFIG={RECORDING_SERVICE_URL:window.RECORDING_SERVICE_URL || 'http://localhost:8002',API_TIMEOUT:10000,RETRY_ATTEMPTS:3,RETRY_DELAY:1000,HEALTH_CHECK_INTERVAL:30000,DEFAULT_CAMERA:null};class ApiClient{constructor(baseUrl){this.baseUrl=baseUrl;}async fetch(endpoint,options={}){const timeoutPromise=new Promise((_,reject)=>{setTimeout(()=> reject(new Error('Request timeout')),CONFIG.API_TIMEOUT);});const fetchPromise=fetch(\`\${this.baseUrl}\${endpoint}\`,options).then(response=>{if(!response.ok){throw new Error(\`HTTP error! status:\${response.status}\`);}return response.json();});try{return await Promise.race([fetchPromise,timeoutPromise]);}catch(error){if(error.message==='Failed to fetch'){throw new Error('Network error-service may be offline');}throw error;}}async fetchWithRetry(endpoint,options={},attempts=CONFIG.RETRY_ATTEMPTS){for(let i=0;i < attempts;i++){try{return await this.fetch(endpoint,options);}catch(error){console.warn(\`Attempt \${i+1}failed:\`,error.message);if(i===attempts-1){throw error;}await new Promise(resolve=> setTimeout(resolve,CONFIG.RETRY_DELAY*Math.pow(2,i)));}}}}class RecordingsPageApp{constructor(){this.api=new ApiClient(CONFIG.RECORDING_SERVICE_URL);this.state={serviceOnline:false,currentCamera:null,cameras:[],selectedCameras:[],availableCameras:[],currentDate:new Date(),selectedDate:new Date(),recordings:[],currentRecording:null,timelineSegments:[],calendarData:{},isLoading:false,playableRecordings:[],unplayableRecordings:[],isInitialLoad:true,pendingAutoSelection:null};this.healthCheckInterval=null;this.videoRetryCount=0;this.initializeElements();this.attachEventListeners();this.initialize();}isRecordingPlayable(recording){const filename=recording.filename || '';const fileSize=recording.file_size || 0;if(filename.endsWith('.avi')){return{playable:false,reason:'AVI format not supported in browsers',format:'avi'};}if(filename.endsWith('_600.mp4')&& fileSize < 10*1024*1024){return{playable:false,reason:'Legacy OpenCV recording(corrupted)',format:'legacy'};}if(filename.includes('_202')&& filename.endsWith('.mp4')){return{playable:true,reason:'FFmpeg MP4 recording',format:'ffmpeg'};}if(filename.endsWith('.mp4')){return{playable:true,reason:'MP4 format supported',format:'mp4'};}return{playable:false,reason:'Unknown format',format:'unknown'};}initializeElements(){this.serviceStatus=document.getElementById('serviceStatus');this.serviceStatusText=document.getElementById('serviceStatusText');this.cameraList=document.getElementById('cameraList');this.cameraCount=document.getElementById('cameraCount');this.calendarGrid=document.getElementById('calendarGrid');this.calendarMonth=document.getElementById('calendarMonth');this.recordingsList=document.getElementById('recordingsList');this.recordingCount=document.getElementById('recordingCount');this.prevMonthBtn=document.getElementById('prevMonth');this.nextMonthBtn=document.getElementById('nextMonth');this.todayBtn=document.getElementById('todayBtn');this.videoPlayer=document.getElementById('videoPlayer');this.videoLoading=document.getElementById('videoLoading');this.videoError=document.getElementById('videoError');this.videoErrorMessage=document.getElementById('videoErrorMessage');this.videoPlaceholder=document.getElementById('videoPlaceholder');this.timelineTrack=document.getElementById('timelineTrack');this.playPauseBtn=document.getElementById('playPauseBtn');this.skipBackBtn=document.getElementById('skipBackBtn');this.skipForwardBtn=document.getElementById('skipForwardBtn');this.timeDisplay=document.getElementById('timeDisplay');this.speedSelect=document.getElementById('speedSelect');}attachEventListeners(){this.prevMonthBtn.addEventListener('click',()=>{this.state.currentDate.setMonth(this.state.currentDate.getMonth()-1);this.renderCalendar();this.loadCalendarData();});this.nextMonthBtn.addEventListener('click',()=>{this.state.currentDate.setMonth(this.state.currentDate.getMonth()+1);this.renderCalendar();this.loadCalendarData();});this.todayBtn.addEventListener('click',async()=>{const today=new Date();this.state.currentDate=new Date(today);this.state.selectedDate=new Date(today);this.renderCalendar();this.state.selectedCameras=[];this.state.currentCamera=null;this.state.isInitialLoad=true;console.log('Navigating to today,loading cameras and auto-selecting active ones...');await this.loadCalendarData();await this.loadCamerasForDate();});this.playPauseBtn.addEventListener('click',()=> this.togglePlayPause());this.skipBackBtn.addEventListener('click',()=>{if(this.videoPlayer.readyState >=2){this.videoPlayer.currentTime=Math.max(0,this.videoPlayer.currentTime-10);}});this.skipForwardBtn.addEventListener('click',()=>{if(this.videoPlayer.readyState >=2){this.videoPlayer.currentTime=Math.min(this.videoPlayer.duration,this.videoPlayer.currentTime+10);}});this.speedSelect.addEventListener('change',(e)=>{this.videoPlayer.playbackRate=parseFloat(e.target.value);});this.videoPlayer.addEventListener('loadstart',()=>{this.showVideoLoading();});this.videoPlayer.addEventListener('loadeddata',()=>{this.hideVideoLoading();this.enableControls();this.videoRetryCount=0;});this.videoPlayer.addEventListener('timeupdate',()=>{this.updateTimeDisplay();});this.videoPlayer.addEventListener('play',()=>{this.playPauseBtn.innerHTML='<i class="fas fa-pause"></i>';});this.videoPlayer.addEventListener('pause',()=>{this.playPauseBtn.innerHTML='<i class="fas fa-play"></i>';});this.videoPlayer.addEventListener('error',(e)=>{this.handleVideoError(e);});this.videoPlayer.addEventListener('loadstart',()=>{console.log('Video load started');});this.videoPlayer.addEventListener('loadedmetadata',()=>{console.log('Video metadata loaded:',{duration:this.videoPlayer.duration,videoWidth:this.videoPlayer.videoWidth,videoHeight:this.videoPlayer.videoHeight});});this.videoPlayer.addEventListener('loadeddata',()=>{console.log('Video data loaded successfully');});this.videoPlayer.addEventListener('canplay',()=>{console.log('Video can start playing');});this.timelineTrack.addEventListener('click',(e)=>{this.handleTimelineClick(e);});}async initialize(){try{await this.checkServiceHealth();this.startHealthChecks();if(this.state.serviceOnline){const today=new Date();this.state.currentDate=new Date(today);this.state.selectedDate=new Date(today);this.renderCalendar();await this.loadCalendarData();console.log('Auto-loading cameras for today:',this.formatDate(today));await this.loadCamerasForDate();}}catch(error){console.error('Initialization error:',error);this.showStatus('Failed to initialize','error');}}async checkServiceHealth(){try{await this.api.fetch('/health',{method:'GET'});this.setServiceStatus(true);}catch(error){console.warn('Service health check failed:',error);this.setServiceStatus(false);}}setServiceStatus(online){this.state.serviceOnline=online;if(online){this.serviceStatus.className='service-status online';this.serviceStatusText.textContent='Recording service online';this.enableInterface();}else{this.serviceStatus.className='service-status offline';this.serviceStatusText.textContent='Recording service offline';this.disableInterface();}}startHealthChecks(){if(this.healthCheckInterval){clearInterval(this.healthCheckInterval);}this.healthCheckInterval=setInterval(()=>{this.checkServiceHealth();},CONFIG.HEALTH_CHECK_INTERVAL);}enableInterface(){this.prevMonthBtn.disabled=false;this.nextMonthBtn.disabled=false;this.todayBtn.disabled=false;}disableInterface(){this.prevMonthBtn.disabled=true;this.nextMonthBtn.disabled=true;this.todayBtn.disabled=true;this.disableControls();this.renderEmptyCameraList('Service offline');}enableControls(){this.playPauseBtn.disabled=false;this.skipBackBtn.disabled=false;this.skipForwardBtn.disabled=false;this.speedSelect.disabled=false;}disableControls(){this.playPauseBtn.disabled=true;this.skipBackBtn.disabled=true;this.skipForwardBtn.disabled=true;this.speedSelect.disabled=true;}async loadCameras(){try{const response=await this.api.fetchWithRetry('/api/v1/recordings/sources');if(!response.sources){throw new Error('Invalid response format from recording sources');}this.state.cameras=response.sources.map(source=>({id:source.camera_id,name:source.display_name,isActive:source.is_active,status:source.status,recordingCount:source.recording_count,storageUsedMb:source.storage_used_mb,hasRecordings:source.has_recordings}));this.state.cameras.sort((a,b)=>{if(a.isActive && !b.isActive)return-1;if(!a.isActive && b.isActive)return 1;return a.name.localeCompare(b.name);});this.renderCameraSelector();if(!this.state.currentCamera && this.state.cameras.length > 0){const defaultCamera=this.state.cameras.find(cam=> cam.hasRecordings)|| this.state.cameras[0];this.state.currentCamera=defaultCamera.id;this.cameraSelect.value=this.state.currentCamera;}console.log('Loaded recording sources:',{total:response.total_count,active:response.active_count,deleted:response.deleted_count,cameras:this.state.cameras});}catch(error){console.error('Failed to load recording sources:',error);this.showStatus('Failed to load recording sources','error');this.state.cameras=[];this.renderCameraSelector();}}renderCameraSelector(){this.cameraSelect.innerHTML=this.state.cameras.map(camera=>{const statusIndicator=camera.isActive ? '✅':'⚠️';const storageInfo=camera.storageUsedMb ? \`(\${(camera.storageUsedMb/1024).toFixed(1)}GB-\${camera.recordingCount}clips)\`:'';return \`<option value="\${camera.id}">\${statusIndicator}\${camera.name}\${storageInfo}</option>\`;}).join('');if(this.state.currentCamera){this.cameraSelect.value=this.state.currentCamera;}}renderCalendar(){const year=this.state.currentDate.getFullYear();const month=this.state.currentDate.getMonth();const today=new Date();this.calendarMonth.textContent=new Intl.DateTimeFormat('en-US',{month:'long',year:'numeric'}).format(this.state.currentDate);this.calendarGrid.innerHTML='';const firstDay=new Date(year,month,1).getDay();const daysInMonth=new Date(year,month+1,0).getDate();for(let i=0;i < firstDay;i++){const emptyDay=document.createElement('div');emptyDay.className='calendar-day disabled';this.calendarGrid.appendChild(emptyDay);}for(let day=1;day <=daysInMonth;day++){const dayElement=document.createElement('div');dayElement.className='calendar-day';dayElement.textContent=day;const date=new Date(year,month,day);if(this.isSameDay(date,today)){dayElement.classList.add('today');}if(this.isSameDay(date,this.state.selectedDate)){dayElement.classList.add('selected');}const dateKey=this.formatDate(date);if(this.state.calendarData[dateKey]){dayElement.classList.add('has-recordings');}if(date > today){dayElement.classList.add('disabled');}else{dayElement.addEventListener('click',async()=>{this.state.selectedDate=date;this.renderCalendar();this.state.selectedCameras=[];this.state.currentCamera=null;this.state.isInitialLoad=true;console.log('Date selected:',this.formatDate(date),'-loading cameras and auto-selecting...');await this.loadCamerasForDate();});}this.calendarGrid.appendChild(dayElement);}}async loadCalendarData(){if(!this.state.serviceOnline)return;try{const response=await this.api.fetchWithRetry('/api/v1/recordings/calendar/dates');if(!response.dates){console.warn('No dates returned from calendar endpoint');return;}this.state.calendarData={};response.dates.forEach(date=>{this.state.calendarData[date]={has_recordings:true};});console.log('Loaded calendar data for',response.dates.length,'dates:',response.dates);this.renderCalendar();}catch(error){console.warn('Failed to load calendar data:',error);}}async loadCamerasForDateForced(){if(!this.state.selectedDate){this.state.selectedDate=new Date();}try{const dateStr=this.formatDate(this.state.selectedDate);console.log('Force loading cameras for date:',dateStr);const response=await this.api.fetchWithRetry('/api/v1/recordings/date/'+dateStr+'/cameras');if(!response.cameras){console.warn('No cameras in response:',response);return;}this.state.availableCameras=response.cameras.map(camera=>({id:camera.camera_id,name:camera.display_name,location:camera.display_name || 'Unknown Location',isActive:camera.is_active,status:camera.status==='deleted' ? 'archived':camera.status,recordingCount:camera.recording_count,storageUsedMb:camera.storage_used_mb,hasRecordings:camera.has_recordings}));console.log('Force loaded',this.state.availableCameras.length,'cameras for',dateStr);console.log('Available cameras:',this.state.availableCameras);this.state.serviceOnline=true;if(!this.state.currentCamera && this.state.availableCameras.length > 0){const activeCamera=this.state.availableCameras.find(cam=> cam.isActive);const defaultCamera=activeCamera || this.state.availableCameras[0];this.state.currentCamera=defaultCamera.id;console.log('Auto-selected camera:',defaultCamera.name);}this.renderCameraList();}catch(error){console.error('Failed to force load cameras:',error);this.renderEmptyCameraList('Failed to load cameras');}}async loadCamerasForDate(){if(!this.state.serviceOnline || !this.state.selectedDate){this.renderEmptyCameraList('No date selected');return;}this.showCameraListLoading();try{const dateStr=this.formatDate(this.state.selectedDate);const response=await this.api.fetchWithRetry('/api/v1/recordings/date/'+dateStr+'/cameras');if(!response.cameras){throw new Error('Invalid response format from cameras endpoint');}this.state.availableCameras=response.cameras.map(camera=>({id:camera.camera_id,name:camera.display_name,location:camera.display_name || 'Unknown Location',isActive:camera.is_active,status:camera.status==='deleted' ? 'archived':camera.status,recordingCount:camera.recording_count,storageUsedMb:camera.storage_used_mb,hasRecordings:camera.has_recordings}));console.log('Found',this.state.availableCameras.length,'cameras for',dateStr);console.log('Available cameras for auto-selection:',this.state.availableCameras);if(!this.state.currentCamera && this.state.availableCameras.length > 0){const activeCamera=this.state.availableCameras.find(cam=> cam.isActive);const defaultCamera=activeCamera || this.state.availableCameras[0];this.state.currentCamera=defaultCamera.id;console.log('Auto-selected camera:',defaultCamera.name);}this.renderCameraList();}catch(error){console.error('Failed to load cameras for date:',error);this.renderEmptyCameraList('Failed to load cameras');}}showCameraListLoading(){this.cameraList.innerHTML='<div class="camera-list-loading"><div class="skeleton skeleton-camera-item"></div><div class="skeleton skeleton-camera-item"></div></div>';this.cameraCount.textContent='Loading...';}renderEmptyCameraList(message){this.cameraList.innerHTML='<div class="camera-list-empty"><i class="fas fa-video-slash"></i><p>'+message+'</p></div>';this.cameraCount.textContent='No cameras';}renderCameraList(){if(!this.state.availableCameras || this.state.availableCameras.length===0){if(!this.state.selectedDate){this.state.selectedDate=new Date();}this.loadCamerasForDateForced();this.renderEmptyCameraList('Loading cameras...');return;}if(!this.state.selectedCameras || this.state.selectedCameras.length===0){const today=new Date();const isToday=this.isSameDay(this.state.selectedDate,today);if(isToday){const activeCameras=this.state.availableCameras.filter(c=> c.isActive===true && c.status !=='archived');if(activeCameras.length > 0){console.log('Active camera found for today:',activeCameras[0].location,'ID:',activeCameras[0].id);this.state.pendingAutoSelection=activeCameras[0].id;}else{const camerasWithRecordings=this.state.availableCameras.filter(c=> c.hasRecordings);if(camerasWithRecordings.length > 0){console.log('Camera with recordings found for today:',camerasWithRecordings[0].location,'ID:',camerasWithRecordings[0].id);this.state.pendingAutoSelection=camerasWithRecordings[0].id;}}}else{const camerasWithRecordings=this.state.availableCameras.filter(c=> c.hasRecordings);if(camerasWithRecordings.length > 0){console.log('Camera with recordings found for date:',this.formatDate(this.state.selectedDate),camerasWithRecordings[0].location,'ID:',camerasWithRecordings[0].id);this.state.pendingAutoSelection=camerasWithRecordings[0].id;}}}this.updateCameraListHeader();this.cameraList.innerHTML=this.state.availableCameras.map(camera=>{const isActive=camera.isActive===true && camera.status !=='archived';const statusClass=isActive ? 'recording':'archived';const statusText=isActive ? 'Recording':'Archived';const isSelected=this.state.selectedCameras && this.state.selectedCameras.includes(camera.id);const location=camera.location || camera.name || 'Unknown Location';return '<div class="camera-list-item" '+'data-camera-id="'+camera.id+'">'+'<label class="camera-item-label">'+'<input type="checkbox" class="camera-checkbox" '+'data-camera-id="'+camera.id+'" '+(isSelected ? 'checked':'')+'>'+'<span class="camera-location">'+location+'</span>'+'</label>'+'</div>';}).join('');this.cameraList.querySelectorAll('.camera-checkbox').forEach(checkbox=>{checkbox.addEventListener('change',(e)=>{e.stopPropagation();this.handleCameraSelection(checkbox.dataset.cameraId,checkbox.checked);});});this.cameraList.querySelectorAll('.camera-list-item').forEach(item=>{item.addEventListener('click',(e)=>{if(e.target.type !=='checkbox'){const checkbox=item.querySelector('.camera-checkbox');checkbox.checked=!checkbox.checked;this.handleCameraSelection(checkbox.dataset.cameraId,checkbox.checked);}});});if(this.state.isInitialLoad){this.state.isInitialLoad=false;if(this.state.pendingAutoSelection){console.log('Executing pending auto-selection after UI render:',this.state.pendingAutoSelection);requestAnimationFrame(()=>{setTimeout(()=>{console.log('Auto-selecting camera after page load:',this.state.pendingAutoSelection);this.handleCameraSelection(this.state.pendingAutoSelection,true);this.state.pendingAutoSelection=null;},1000);});}}}handleCameraSelection(cameraId,isSelected){console.log('handleCameraSelection called:',cameraId,'selected:',isSelected);if(!this.state.selectedCameras){this.state.selectedCameras=[];}if(isSelected){if(!this.state.selectedCameras.includes(cameraId)){this.state.selectedCameras.push(cameraId);}this.state.currentCamera=cameraId;console.log('Current camera set to:',cameraId);}else{const index=this.state.selectedCameras.indexOf(cameraId);if(index >-1){this.state.selectedCameras.splice(index,1);}if(this.state.currentCamera===cameraId && this.state.selectedCameras.length > 0){this.state.currentCamera=this.state.selectedCameras[0];}}const checkboxes=this.cameraList.querySelectorAll('.camera-checkbox');console.log('Found',checkboxes.length,'checkboxes to update');checkboxes.forEach(checkbox=>{const isCurrentlySelected=this.state.selectedCameras.includes(checkbox.dataset.cameraId);const wasChecked=checkbox.checked;checkbox.checked=isCurrentlySelected;console.log('Checkbox update:',{cameraId:checkbox.dataset.cameraId,wasChecked:wasChecked,nowChecked:checkbox.checked,shouldBeSelected:isCurrentlySelected});const parentItem=checkbox.closest('[data-camera-id]');if(parentItem){if(isCurrentlySelected){parentItem.classList.add('selected');}else{parentItem.classList.remove('selected');}}});this.updateCameraListHeader();if(this.state.selectedCameras.length > 0 && isSelected){console.log('Loading recordings for camera selection:',cameraId);setTimeout(()=>{this.loadRecordingsForDate();},100);}}updateCameraListHeader(){if(!this.state.selectedCameras || this.state.selectedCameras.length===0){this.cameraCount.textContent='No cameras selected';return;}const selectedCameraObjects=this.state.availableCameras.filter(c=> this.state.selectedCameras.includes(c.id));if(selectedCameraObjects.length===this.state.availableCameras.length){this.cameraCount.textContent='All Cameras';}else if(selectedCameraObjects.length===1){const location=selectedCameraObjects[0].location || selectedCameraObjects[0].name;this.cameraCount.textContent=location;}else if(selectedCameraObjects.length <=3){const locations=selectedCameraObjects.map(c=> c.location || c.name);this.cameraCount.textContent=locations.join(',');}else{const firstCamera=selectedCameraObjects[0].location || selectedCameraObjects[0].name;const moreCount=selectedCameraObjects.length-1;this.cameraCount.textContent=firstCamera+'+'+moreCount+' more';}}async loadRecordingsForDate(){if(!this.state.serviceOnline || !this.state.currentCamera){console.log('Cannot load recordings-service offline or no camera selected',{serviceOnline:this.state.serviceOnline,currentCamera:this.state.currentCamera});this.renderEmptyRecordingsList('Service offline');return;}console.log('Loading recordings for camera:',this.state.currentCamera,'on date:',this.formatDate(this.state.selectedDate));this.showRecordingsLoading();try{const dateStr=this.formatDate(this.state.selectedDate);const data=await this.api.fetchWithRetry(\`/api/v1/recordings/cameras/\${this.state.currentCamera}/timeline?date=\${dateStr}\`);this.state.recordings=data.segments || [];this.state.timelineSegments=data.timeline || data.segments || [];this.state.playableRecordings=[];this.state.unplayableRecordings=[];this.state.recordings.forEach(recording=>{const playabilityInfo=this.isRecordingPlayable(recording);recording.playabilityInfo=playabilityInfo;console.log('Recording playability:',{filename:recording.filename,size:recording.file_size,playable:playabilityInfo.playable,reason:playabilityInfo.reason,format:playabilityInfo.format});if(playabilityInfo.playable){this.state.playableRecordings.push(recording);}else{this.state.unplayableRecordings.push(recording);}});this.renderRecordingsList();this.renderTimeline();this.clearVideo();console.log('Playability summary:',{totalRecordings:this.state.recordings.length,playableCount:this.state.playableRecordings.length,unplayableCount:this.state.unplayableRecordings.length,serviceOnline:this.state.serviceOnline});if(this.state.playableRecordings.length > 0 && this.state.serviceOnline){console.log('Auto-playing first recording:',this.state.playableRecordings[0].filename);await this.playRecording(this.state.playableRecordings[0]);}else if(this.state.recordings.length > 0 && this.state.playableRecordings.length===0){console.log('No playable recordings found,showing unplayable message');this.showUnplayableMessage();}}catch(error){console.error('Failed to load recordings:',error);this.showStatus('Failed to load recordings','error');this.renderEmptyRecordingsList('Failed to load recordings');this.state.recordings=[];this.state.timelineSegments=[];this.renderTimeline();}}showRecordingsLoading(){this.recordingsList.innerHTML=\` <div class="skeleton skeleton-item"></div> <div class="skeleton skeleton-item"></div> <div class="skeleton skeleton-item"></div> \`;this.recordingCount.textContent='Loading...';}renderRecordingsList(){const playableCount=this.state.playableRecordings.length;const totalCount=this.state.recordings.length;this.recordingCount.innerHTML=\`\${totalCount}clips\`;if(playableCount < totalCount){this.recordingCount.innerHTML+=\`<span class="playable-count">(\${playableCount}playable)</span>\`;}if(this.state.recordings.length===0){this.renderEmptyRecordingsList('No recordings found');return;}this.recordingsList.innerHTML=this.state.recordings.map((recording,index)=>{const startTime=new Date(recording.start_time);const duration=this.formatDuration(recording.duration_seconds || 0);const fileSize=this.formatFileSize(recording.file_size || 0);const playabilityInfo=recording.playabilityInfo ||{};const isPlayable=playabilityInfo.playable;const format=playabilityInfo.format || 'unknown';let formatBadge='';if(format==='avi'){formatBadge='<span class="format-badge avi">AVI</span>';}else if(format==='legacy'){formatBadge='<span class="format-badge legacy">Legacy MP4</span>';}else if(format==='mp4' && isPlayable){formatBadge='<span class="format-badge mp4">MP4</span>';}return \` <div class="recording-item \${!isPlayable ? 'unplayable':''}" data-index="\${index}" title="\${!isPlayable ? playabilityInfo.reason:''}"> <div class="recording-info"> <div class="recording-time"> \${startTime.toLocaleTimeString()}\${formatBadge}</div> <div class="recording-details"> <span><i class="fas fa-clock"></i> \${duration}</span> <span><i class="fas fa-hdd"></i> \${fileSize}</span> </div> </div> <div class="recording-play"> <i class="fas \${!isPlayable ? 'fa-times-circle':'fa-play-circle'}"></i> </div> </div> \`;}).join('');this.recordingsList.querySelectorAll('.recording-item').forEach((item)=>{item.addEventListener('click',async(e)=>{const index=parseInt(e.currentTarget.dataset.index);const recording=this.state.recordings[index];if(recording.playabilityInfo && !recording.playabilityInfo.playable){this.showStatus(\`Cannot play:\${recording.playabilityInfo.reason}\`,'warning',5000);}else{await this.playRecording(recording);}});});}renderEmptyRecordingsList(message){this.recordingsList.innerHTML=\` <div class="empty-state"> <i class="fas fa-film"></i> <p>\${message}</p> </div> \`;this.recordingCount.textContent='0 clips';}renderTimeline(){this.timelineTrack.innerHTML='';if(this.state.timelineSegments.length===0)return;const dayStart=new Date(this.state.selectedDate);dayStart.setHours(0,0,0,0);const dayEnd=new Date(this.state.selectedDate);dayEnd.setHours(23,59,59,999);const dayDuration=dayEnd-dayStart;this.state.timelineSegments.forEach((segment,index)=>{const startTime=new Date(segment.start_time);const duration=segment.duration_seconds || 0;const endTime=new Date(startTime.getTime()+duration*1000);const startPercent=Math.max(0,((startTime-dayStart)/dayDuration)*100);const widthPercent=Math.min(100-startPercent,((endTime-startTime)/dayDuration)*100);if(widthPercent > 0){const segmentEl=document.createElement('div');segmentEl.className='timeline-segment';const recording=this.state.recordings.find(r=> r.filename===segment.filename);if(recording && recording.playabilityInfo && !recording.playabilityInfo.playable){segmentEl.classList.add('unplayable');segmentEl.title=recording.playabilityInfo.reason;}segmentEl.style.left=\`\${startPercent}%\`;segmentEl.style.width=\`\${widthPercent}%\`;segmentEl.dataset.index=index;if(this.state.currentRecording && this.state.currentRecording.filename===segment.filename){segmentEl.classList.add('playing');}this.timelineTrack.appendChild(segmentEl);}});}handleTimelineClick(e){if(!this.state.timelineSegments.length)return;const rect=this.timelineTrack.getBoundingClientRect();const x=e.clientX-rect.left;const percentage=x/rect.width;const dayStart=new Date(this.state.selectedDate);dayStart.setHours(0,0,0,0);const dayDuration=24*60*60*1000;const clickTime=new Date(dayStart.getTime()+dayDuration*percentage);for(let i=0;i < this.state.timelineSegments.length;i++){const segment=this.state.timelineSegments[i];const startTime=new Date(segment.start_time);const endTime=new Date(startTime.getTime()+(segment.duration_seconds || 0)*1000);if(clickTime >=startTime && clickTime <=endTime){const recording=this.state.recordings.find(r=> r.filename===segment.filename || r.id===segment.id);if(recording){this.playRecording(recording);}break;}}}async playRecording(recording){if(!this.state.serviceOnline){this.showStatus('Recording service is offline','warning');return;}try{this.state.currentRecording=recording;this.recordingsList.querySelectorAll('.recording-item').forEach(item=>{item.classList.remove('playing');});const recordingElements=this.recordingsList.querySelectorAll('.recording-item');const index=this.state.recordings.indexOf(recording);if(index >=0 && recordingElements[index]){recordingElements[index].classList.add('playing');}this.renderTimeline();this.videoPlaceholder.style.display='none';this.videoPlayer.style.display='block';this.videoError.style.display='none';const recordingServiceUrl=(typeof CONFIG !=='undefined' && CONFIG.RECORDING_SERVICE_URL)? CONFIG.RECORDING_SERVICE_URL:'http://localhost:8002';const videoUrl=\`\${recordingServiceUrl}/api/v1/recordings/stream/\${recording.filename}\`;console.log('CONFIG exists?:',typeof CONFIG !=='undefined');console.log('Recording Service URL:',recordingServiceUrl);console.log('window.location.hostname:',window.location.hostname);console.log('Loading video:',{filename:recording.filename,url:videoUrl,recording:recording});this.videoPlayer.removeAttribute('src');this.videoPlayer.load();console.log('Setting video source to:',videoUrl);let finalUrl=videoUrl;if(!videoUrl.startsWith('http')){finalUrl=\`http://localhost:8002\${videoUrl.startsWith('/')? videoUrl:'/'+videoUrl}\`;console.log('Converted to absolute URL:',finalUrl);}if(!finalUrl.includes(':8002')){console.error('Invalid video URL detected:',finalUrl);console.error('CONFIG object:',CONFIG);finalUrl=\`http://localhost:8002/api/v1/recordings/stream/\${recording.filename}\`;console.log('Using corrected URL:',finalUrl);}this.videoPlayer.src=finalUrl;console.log('After setting src,videoPlayer.src=',this.videoPlayer.src);console.log('After setting src,videoPlayer.currentSrc=',this.videoPlayer.currentSrc);this.videoPlayer.load();console.log('Video load()called,waiting for events...');}catch(error){console.error('Failed to play recording:',error);this.showStatus('Failed to play recording','error');this.showVideoError();}}clearVideo(){this.videoPlayer.pause();this.videoPlayer.src='';this.videoPlayer.style.display='none';this.videoPlaceholder.style.display='flex';this.videoError.style.display='none';this.state.currentRecording=null;this.disableControls();this.updateTimeDisplay();}showVideoLoading(){this.videoLoading.style.display='flex';this.videoError.style.display='none';}hideVideoLoading(){this.videoLoading.style.display='none';}showVideoError(){this.videoError.style.display='flex';this.videoLoading.style.display='none';this.videoPlayer.style.display='none';this.disableControls();}handleVideoError(e){console.error('Video playback error:',e);const video=e.target;console.error('Complete video error debug info:',{videoSrc:video.src,currentSrc:video.currentSrc,networkState:video.networkState,readyState:video.readyState,errorCode:video.error ? video.error.code:'No error code',errorMessage:video.error ? video.error.message:'No error message',errorDetails:this.getVideoErrorDetails(video.error),currentTime:video.currentTime,duration:video.duration,videoWidth:video.videoWidth,videoHeight:video.videoHeight});if(!video.src || video.src==='' || video.src===window.location.href || video.src.endsWith('8080/')|| video.src.includes('localhost:8080')){console.log('Ignoring video error-no valid source set:',video.src);return;}this.showVideoError();this.showStatus('Unable to play video','error');}getVideoErrorDetails(error){if(!error)return 'No error object';const errorTypes={1:'MEDIA_ERR_ABORTED-The video playback was aborted',2:'MEDIA_ERR_NETWORK-A network error caused the video download to fail',3:'MEDIA_ERR_DECODE-The video playback was aborted due to a corruption problem',4:'MEDIA_ERR_SRC_NOT_SUPPORTED-The video format is not supported'};return errorTypes[error.code] || \`Unknown error code:\${error.code}\`;}togglePlayPause(){if(!this.videoPlayer.src || this.videoPlayer.readyState < 2)return;if(this.videoPlayer.paused){this.videoPlayer.play().catch(error=>{console.error('Play failed:',error);this.showStatus('Failed to play video','error');});}else{this.videoPlayer.pause();}}updateTimeDisplay(){const current=this.formatTime(this.videoPlayer.currentTime || 0);const duration=this.formatTime(this.videoPlayer.duration || 0);this.timeDisplay.textContent=\`\${current}/\${duration}\`;}formatDate(date){const year=date.getFullYear();const month=String(date.getMonth()+1).padStart(2,'0');const day=String(date.getDate()).padStart(2,'0');return \`\${year}-\${month}-\${day}\`;}formatTime(seconds){if(!isFinite(seconds))return '--:--:--';const h=Math.floor(seconds/3600);const m=Math.floor((seconds % 3600)/60);const s=Math.floor(seconds % 60);return \`\${String(h).padStart(2,'0')}:\${String(m).padStart(2,'0')}:\${String(s).padStart(2,'0')}\`;}formatDuration(seconds){if(!seconds || !isFinite(seconds))return '0s';if(seconds < 60)return \`\${Math.floor(seconds)}s\`;const minutes=Math.floor(seconds/60);const secs=Math.floor(seconds % 60);if(minutes < 60)return \`\${minutes}m \${secs}s\`;const hours=Math.floor(minutes/60);const mins=minutes % 60;return \`\${hours}h \${mins}m\`;}formatFileSize(bytes){if(!bytes || !isFinite(bytes))return '0 B';const units=['B','KB','MB','GB'];let size=bytes;let unitIndex=0;while(size >=1024 && unitIndex < units.length-1){size/=1024;unitIndex++;}return \`\${size.toFixed(1)}\${units[unitIndex]}\`;}isSameDay(date1,date2){return date1.getFullYear()===date2.getFullYear()&& date1.getMonth()===date2.getMonth()&& date1.getDate()===date2.getDate();}showStatus(message,type='info',duration=3000){document.querySelectorAll('.status-message').forEach(el=> el.remove());const statusEl=document.createElement('div');statusEl.className=\`status-message \${type}\`;statusEl.innerHTML=\` <i class="fas fa-\${type==='error' ? 'exclamation-circle':type==='success' ? 'check-circle':type==='warning' ? 'exclamation-triangle':'info-circle'}"></i> <span>\${message}</span> \`;document.body.appendChild(statusEl);if(duration > 0){setTimeout(()=>{statusEl.remove();},duration);}}showUnplayableMessage(){const videoContainer=document.querySelector('.video-container');if(!videoContainer)return;this.videoPlaceholder.style.display='none';this.videoPlayer.style.display='none';this.videoError.style.display='none';const messageDiv=document.createElement('div');messageDiv.className='unplayable-message';messageDiv.style.position='absolute';messageDiv.style.top='50%';messageDiv.style.left='50%';messageDiv.style.transform='translate(-50%,-50%)';messageDiv.style.maxWidth='400px';messageDiv.innerHTML=\` <i class="fas fa-exclamation-triangle"></i> <div> <strong>No playable recordings</strong><br> All recordings for this date are in legacy formats(AVI or corrupted MP4)that cannot be played in browsers. New recordings will use the correct MP4 format. </div> \`;videoContainer.querySelector('.unplayable-message')?.remove();videoContainer.appendChild(messageDiv);}destroy(){if(this.healthCheckInterval){clearInterval(this.healthCheckInterval);}this.state.pendingAutoSelection=null;this.videoPlayer.pause();this.videoPlayer.removeAttribute('src');this.videoPlayer.load();}}let recordingsPage;recordingsPage=new RecordingsPageApp();setTimeout(()=>{if(recordingsPage && recordingsPage.renderCameraList){recordingsPage.renderCameraList();}},500);window.recordingsPage=recordingsPage;`;document.head.appendChild(script);}destroy(){if(window.recordingsPage){window.recordingsPage.destroy();}}}export default RecordingsPage;